def title_case(text):
    SMALL_WORDS = {"a", "an", "and", "the", "of", "in", "on", "or", "to", "at", "by", "for"}
    words = text.split()
    result = []
    for i, word in enumerate(words):
        lower = word.lower()
        if i == 0 or lower not in SMALL_WORDS:
            result.append(lower.capitalize())
        else:
            result.append(lower)
    return " ".join(result)


